package sarif

import (
	"compress/gzip"
	"io"
	"os"
	"strconv"
	"strings"

	v2_1_0_turboscan "github.com/github/turboscan/ts/sarif/v2_1_0_turboscan"
	"github.com/mailru/easyjson"

	"github.com/pkg/errors"
)

type DecodingError struct {
	error
}

func (e DecodingError) Error() string {
	// easyjson will include JSON fragments in its error messages
	// if these contain NULL characters they cannot be saved by MySQL
	// replace any unprintable characters using strconv.Quote and then strip off the quotes
	msg := strconv.Quote(e.error.Error())
	return msg[1 : len(msg)-1]
}

// Decode reads JSON from reader into a fresh SARIF struct.
func Decode(data []byte) (*v2_1_0_turboscan.SARIF, error) {
	// Parse a restricted subset of the SARIF.
	internalSARIF := &v2_1_0_turboscan.SARIF{}
	err := easyjson.Unmarshal(data, internalSARIF)
	if err != nil {
		return nil, errors.Wrap(DecodingError{err}, "parsing restricted subset of SARIF data has failed")
	}
	internalSARIF.Normalise()
	return internalSARIF, nil
}

// FromFile reads a SARIF from a JSON file
func FromFile(filePath string) (*v2_1_0_turboscan.SARIF, error) {
	f, err := os.Open(filePath)
	if err != nil {
		return nil, errors.Wrapf(err, "opening SARIF file %q has failed", filePath)
	}
	defer f.Close()

	var bytes []byte
	if strings.HasSuffix(filePath, ".gz") {
		var gzipReader *gzip.Reader
		gzipReader, err = gzip.NewReader(f)
		if err != nil {
			return nil, err
		}
		defer gzipReader.Close()
		bytes, err = io.ReadAll(gzipReader)
	} else {
		bytes, err = io.ReadAll(f)
	}
	if err != nil {
		return nil, errors.Wrap(err, "reading SARIF file into buffer has failed")
	}

	return Decode(bytes)
}

// ResultsByAlertNumber returns a map of the SARIF results based on their corresponding LogicalAlert number.
// This will only work for the processed SARIFs generated by turboscan.
func ResultsByAlertNumber(sarif *v2_1_0_turboscan.SARIF) (map[uint32]*v2_1_0_turboscan.Result, error) {
	resultMap := make(map[uint32]*v2_1_0_turboscan.Result)
	for _, run := range sarif.Runs {
		if run.Results == nil {
			continue
		}
		for _, result := range run.Results {
			if result.Properties != nil && result.Properties.GithubAlertNumber != 0 {
				resultMap[uint32(result.Properties.GithubAlertNumber)] = result
			}
		}
	}
	return resultMap, nil
}
